arguments.command:
sleep 20 && cd /tmp/friends-conv && git fetch origin --prune >/dev/null 2>&1 && python3 - <<'PY'
import subprocess
branches=['rachel','monica','phoebe','joey','chandler','ross']
seen=set(); count=0
for b in branches:
    out=subprocess.check_output(['git','-C','/tmp/friends-conv','log','--reverse','--format=%H',f'origin/friend/{b}'],text=True).split()
    for sha in out:
        msg=subprocess.check_output(['git','-C','/tmp/friends-conv','show','-s','--format=%B',sha],text=True)
        if 'Friend-Message: 1' in msg:
            ep=''
            for line in msg.splitlines():
                if line.startswith('Episode: '):
                    ep=line.split(':',1)[1].strip()
            if ep=='S06/E19':
                count+=1; seen.add(sha)
print('remote friend-message count S06/E19:',count)
PY
